/**
 * Codex Hooks Compile Target (mt#3854)
 *
 * Reads hook sources from `.minsky/hooks/*.ts` and emits `.codex/hooks/<name>.ts`,
 * identically to the `claude-hooks` target — same shebang, same generation
 * banner, same `.minsky/` provenance line, same 0o755. The shared machinery is
 * in `./hook-copy-target`; this module is the Codex construction of it.
 *
 * ## Why this exists
 *
 * `.codex/` held a HAND-MADE port of the Claude harness config. Generated by
 * nothing, it was refreshed by nothing: measured 2026-08-22 it carried 93 hook
 * files against `.claude/hooks`'s 167 — **75 guards missing**, having not moved
 * at all since 2026-07-29. Making it a compile output is what stops a harness
 * config fossilizing, and it is the whole reason this target exists.
 *
 * ## What this target does NOT emit, and why that matters
 *
 * It emits hook SOURCES only. It does not emit `.codex/hooks.json` — the
 * manifest that says which hook runs on which event with which matcher. That is
 * **mt#4431**, split out because it carries a design question this copy does
 * not:
 *
 * Codex's `PreToolUse` intercepts **Bash only**; `apply_patch`, Edit/Write/Read,
 * web fetch and **MCP tool calls do not fire it**. Measured against the
 * hand-made manifest, **12 of its 13 `PreToolUse` matcher entries cannot fire**
 * — including the entire merge-gate chain, which hangs off
 * `mcp__minsky__session_pr_merge`. Emitting that corpus verbatim would produce a
 * manifest that reads as current and enforces almost nothing, which is worse
 * than the fossil because the fossil at least looks stale.
 *
 * So a fresh `.codex/hooks/**` is necessary and not sufficient: the scripts are
 * current, and what invokes them is mt#4431's question. Do not read this
 * target's success as "the guards now run under Codex."
 *
 * @see mt#3854 — this target
 * @see mt#4431 — the manifest, the event mapping, and the reachability question
 * @see ADR-016 — compile pipeline convergence (one pipeline, all targets)
 */

import { makeHookCopyTarget } from "./hook-copy-target";
import type { MinskyCompileTarget } from "../types";

/** Build the codex-hooks target. Factory pattern for test injection. */
function makeCodexHooksTarget(): MinskyCompileTarget {
  return makeHookCopyTarget({
    id: "codex-hooks",
    displayName: "Codex Hooks",
    outputDirSegments: [".codex", "hooks"],
  });
}

export const codexHooksTarget = makeCodexHooksTarget();

/** Export factory for test injection */
export { makeCodexHooksTarget };
